/* Region registry - see regions.h for why this is its own file.
 *
 * The shape, one paragraph (REGIONS.md sections 3.1-3.5):
 *
 *   - A region is a **slot in a registry**, never a first-class value. What the library
 *     hands out is a handle: `{ index, generation }`, a plain copyable value.
 *   - Every slot carries a generation. Dropping a region bumps its generation, so a handle
 *     that outlived its region fails the check instead of reading freed memory; the library
 *     turns that into `failure(staleHandle)` with a source position (ruling: a bug traps, a
 *     condition is a value - REGIONS.md section 3.3).
 *   - Regions and arena blocks are **one tree**: a region's parent is either another region
 *     or the arena level that created it. Dropping a region drops its whole subtree, and
 *     leaving a block drops every region still hanging off that level. That is the hook the
 *     generator emits, one line per release point.
 *   - Membership is the whole point: because the owner is the parent (not the handle),
 *     "copy the handle" and "two owners free the same slot" cannot happen, and a free list
 *     cannot grow a cycle out of user data.
 *
 * Each slot holds a **real arena** (REGIONS.md section 3.1): a region is not a second
 * allocator, it is an arena you keep for later and reset as a unit. That is the whole
 * difference between the two structures - an arena is a stack whose release point is the
 * enclosing block, a region is a pool whose release point is a call - and keeping one
 * allocator means promotion, escape analysis and levels apply to region memory unchanged.
 */

#include "regions.h"

/* The runtime text below is the only copy of this logic: it is what runs, so it is what has
 * to be read and tested (`tests/region/` compiles the emitted C with -Wall -Wextra -Werror
 * and runs it under ASan). It references `extc_arena`, so it has to be appended **after**
 * the arena runtime - the slot holds a real arena (section 3.1), not a second allocator.
 * Split across several `bufPuts` calls because a single literal longer than the 4095
 * characters C99 requires compilers to support draws -Woverlength-strings. */
void regionsEmitRuntime(Arena *a, Buf *out) {
    (void)a;
    bufPuts(out, "/* ---- region registry (REGIONS.md phase 1) ----\n * A region is a slot here, never a value: the library hands out `{ index, generation }`,\n * and dropping bumps the generation so a handle that outlived its region fails a check\n * instead of reading freed memory.\n *\n * The slot holds a **real arena** (section 3.1). A region is not a second allocator: it\n * is an arena you keep and reset as a unit. That is the whole difference between the two\n * structures - an arena is a stack whose release point is the block that owns it, a\n * region is a pool whose release point is a call - and keeping one allocator means the\n * promotion rules, the escape analysis and the level numbering apply unchanged.\n *\n * The registry is per frame (section 3.5): every frame pushes a mark on entry, regions\n * created while it runs are linked into that mark's list, and leaving the frame drops the\n * whole list. A block level is therefore unambiguous - a callee's level 2 is not reachable\n * from its caller's level 2.\n *\n * Emitted only for a program that declares a region extern. */\ntypedef struct ExtcRegion {\n    uint64_t generation;\n    int64_t  parent;        /* parent region, or -1 when this one hangs off a level */\n    int64_t  frame;         /* the frame that created it */\n    int64_t  level;         /* arena level inside that frame (parent < 0 only) */\n    int64_t  firstChild;    /* child regions */\n    int64_t  nextSibling;   /* the parent's child list */\n    int64_t  frameNext;     /* the frame's list of top-level regions */\n    int64_t  freeNext;      /* the free list */\n    extc_arena arena;       /* the region's memory: an arena, released as a unit */\n    int64_t  live;\n} ExtcRegion;\ntypedef struct ExtcFrame { int64_t firstRegion, parent; } ExtcFrame;\nstatic ExtcRegion *extc_regions        = NULL;\nstatic int64_t     extc_regionCap      = 0;\nstatic int64_t     extc_regionLiveN    = 0;\nstatic int64_t     extc_regionFreeHead = -1;\nstatic ExtcFrame *extc_frames          = NULL;\nstatic int64_t     extc_frameCap       = 0;\nstatic int64_t     extc_frameTop       = -1;   /* the innermost frame */\nint64_t extc_region_live(void) { return extc_regionLiveN; }\nint64_t extc_region_capacity(void) { return extc_regionCap; }\nint64_t extc_region_frameDepth(void) { return extc_frameTop + 1; }\n/* Entering a frame: push a mark. Regions created from here on are linked to it. */\nint64_t extc_region_frameEnter(void) {\n    int64_t id = extc_frameTop + 1;\n    if (id >= extc_frameCap) {\n        int64_t want = extc_frameCap ? extc_frameCap * 2 : 64;\n        ExtcFrame *grown = (ExtcFrame *)realloc(extc_frames, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        extc_frames = grown; extc_frameCap = want;\n    }\n    extc_frames[id].firstRegion = -1;\n    extc_frames[id].parent      = extc_frameTop;\n    extc_frameTop = id;\n    return id;\n}\nstatic void extc_region_freeSelf(int64_t rid) {\n    ExtcRegion *r = &extc_regions[rid];\n");
    bufPuts(out, "    extc_arena_destroy(&r->arena);      /* the memory goes, the slot stays on the free list */\n    r->live = 0; r->level = 0; r->parent = -1;\n    r->firstChild = -1;\n    r->freeNext = extc_regionFreeHead;\n    extc_regionFreeHead = rid;\n    extc_regionLiveN--;\n}\nstatic void extc_region_unlinkFrame(int64_t rid) {\n    int64_t fi = extc_regions[rid].frame;\n    if (fi < 0) return;\n    {\n        int64_t *link = &extc_frames[fi].firstRegion;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_regions[rid].frameNext; break; }\n            link = &extc_regions[*link].frameNext;\n        }\n    }\n}\nvoid extc_region_drop(int64_t rid) {\n    int64_t child, parent;\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return;\n    child = extc_regions[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_regions[child].nextSibling;\n        extc_region_drop(child);\n        child = next;\n    }\n    parent = extc_regions[rid].parent;\n    if (parent >= 0) {\n        int64_t *link = &extc_regions[parent].firstChild;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_regions[rid].nextSibling; break; }\n            link = &extc_regions[*link].nextSibling;\n        }\n    } else {\n        extc_region_unlinkFrame(rid);\n    }\n    extc_region_freeSelf(rid);\n}\nint64_t extc_region_new(int64_t parent, int64_t level) {\n    int64_t idx, fi = extc_frameTop;\n    ExtcRegion *r;\n    if (fi < 0) return -1;                     /* outside any frame: no owner, no region */\n    if (extc_regionFreeHead >= 0) {\n        idx = extc_regionFreeHead;\n        extc_regionFreeHead = extc_regions[idx].freeNext;\n    } else {\n        int64_t want = extc_regionCap ? extc_regionCap * 2 : 64, i;\n        ExtcRegion *grown = (ExtcRegion *)realloc(extc_regions, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        for (i = extc_regionCap; i < want; i++) {\n            grown[i].generation = 0; grown[i].parent = -1; grown[i].frame = -1;\n            grown[i].level = 0; grown[i].firstChild = -1; grown[i].nextSibling = -1;\n            grown[i].frameNext = -1; grown[i].freeNext = -1;\n            grown[i].arena.top = NULL; grown[i].arena.spare = NULL; grown[i].live = 0;\n        }\n        extc_regions = grown; idx = extc_regionCap; extc_regionCap = want;\n    }\n    r = &extc_regions[idx];\n    if (r->live) return -1;                    /* a free slot is never live */\n    r->generation++;                           /* first life of a fresh slot: 1 */\n    r->live = 1; r->parent = parent; r->level = level; r->frame = fi;\n    r->firstChild = -1; r->nextSibling = -1; r->frameNext = -1;\n    r->arena.top = NULL; r->arena.spare = NULL;\n    if (parent >= 0) {\n        r->nextSibling = extc_regions[parent].firstChild;\n        extc_regions[parent].firstChild = idx;\n    } else {\n        r->frameNext = extc_frames[fi].firstRegion;\n        extc_frames[fi].firstRegion = idx;\n    }\n    extc_regionLiveN++;\n    return idx;\n}\n");
    bufPuts(out, "uint64_t extc_region_generation(int64_t rid) {\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return 0;\n    return extc_regions[rid].generation;\n}\n/* Keep the region, give its memory back: the parent's epoch moving on has to move the\n * children's with it (section 9.2). The arena object survives, the blocks do not. */\nvoid extc_region_reset(int64_t rid) {\n    int64_t child;\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return;\n    child = extc_regions[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_regions[child].nextSibling;\n        extc_region_drop(child);\n        child = next;\n    }\n    extc_regions[rid].firstChild = -1;\n    extc_arena_destroy(&extc_regions[rid].arena);\n}\n/* The block hook: a region created at this frame's level dies with that block. */\nvoid extc_region_releaseLevel(int64_t frame, int64_t level) {\n    int64_t rid;\n    if (frame < 0 || frame > extc_frameTop || level <= 0) return;\n    rid = extc_frames[frame].firstRegion;\n    while (rid >= 0) {\n        int64_t next = extc_regions[rid].frameNext;\n        if (extc_regions[rid].level == level) extc_region_drop(rid);\n        rid = next;\n    }\n}\n/* The frame hook: everything the frame created, including what its blocks left behind. */\nvoid extc_region_frameLeave(int64_t frame) {\n    int64_t rid;\n    if (frame < 0 || frame > extc_frameTop) return;\n    rid = extc_frames[frame].firstRegion;\n    while (rid >= 0) {\n        int64_t next = extc_regions[rid].frameNext;\n        extc_region_drop(rid);\n        rid = next;\n    }\n    if (frame == extc_frameTop) extc_frameTop = extc_frames[frame].parent;\n}\n/* Memory out of a region, for the library's containers. It is the arena allocator, so the\n * zeroing promise and the failure behaviour are the same ones every other allocation has;\n * only the release point differs (reset/drop/block exit instead of the block that asked).\n * The position is `\"<region>\"` because the allocation is the library's, not a source line\n * the user wrote - the same reason section 3.3 wants @trackCaller for traps. */\nvoid *extc_region_alloc(int64_t rid, int64_t bytes) {\n    if (rid < 0 || rid >= extc_regionCap || !extc_regions[rid].live) return NULL;\n    return extc_arena_alloc(&extc_regions[rid].arena, bytes, \"<region>\", 0);\n}\n");
}
